oakLimbs[3].w = {18,15,13,12,11,9,8,6,5,3.5}
oakLimbs[4].pts = {{303,400},{309,372},{306,346},{312,318},{303,290},{309,262},{313,238},{304,212},{308,190},{314,160},{307,134},{309,110}}
